package pe.edu.upeu.pago.service;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import pe.edu.upeu.pago.dto.*; import pe.edu.upeu.pago.entity.*; import pe.edu.upeu.pago.repository.*;
import java.net.URI; import java.util.*; import java.time.Instant;
@Service @RequiredArgsConstructor
public class ComercioService {
 private final ConfiguracionComercialRepository repo; private final AceptacionCompraRepository aceptaciones;
 @Transactional(readOnly=true) public EstadoComercial obtener(boolean admin){var c=actual();var faltan=pendientes(c);boolean lista=c.isPublicada()&&faltan.isEmpty();var datos=datos(c);if(!admin&&!lista)datos=new DatosComerciales(c.getVersion(),"","","","","","","","",false);return new EstadoComercial(datos,lista,List.copyOf(faltan));}
 @Transactional public EstadoComercial guardar(DatosComerciales d){var c=actual();if(!Objects.equals(c.getVersion(),d.version()))throw new IllegalStateException("La configuración cambió. Recarga antes de guardar.");c.setRazonSocial(d.razonSocial().strip());c.setRuc(d.ruc().strip());c.setDireccion(d.direccion().strip());c.setEmailSoporte(d.emailSoporte().strip());c.setTerminos(d.terminos().strip());c.setPrivacidad(d.privacidad().strip());c.setReembolsos(d.reembolsos().strip());c.setReclamacionesUrl(d.reclamacionesUrl().strip());c.setPublicada(d.publicada());if(d.publicada()&&!pendientes(c).isEmpty())throw new IllegalArgumentException("Completa: "+String.join(", ",pendientes(c)));repo.saveAndFlush(c);return obtener(true);}
 @Transactional public void aceptar(String tipo,Long orden,Long estudiante,String sub,AceptacionRequest r){var c=actual();if(!c.isPublicada()||!pendientes(c).isEmpty())throw new IllegalStateException("La información de compra aún no está publicada.");if(r==null||!Boolean.TRUE.equals(r.acepta())||!Objects.equals(c.getVersion(),r.version()))throw new IllegalArgumentException("Lee y acepta las condiciones vigentes antes de continuar.");if(aceptaciones.existsByTipoAndOrdenIdAndSujetoAndVersionComercial(tipo,orden,sub,c.getVersion()))return;var a=new AceptacionCompra();a.setTipo(tipo);a.setOrdenId(orden);a.setEstudianteId(estudiante);a.setSujeto(sub);a.setVersionComercial(c.getVersion());a.setFecha(Instant.now());a.setTextoAceptado(String.join("\n\n",c.getRazonSocial(),c.getRuc(),c.getDireccion(),c.getEmailSoporte(),c.getTerminos(),c.getPrivacidad(),c.getReembolsos(),c.getReclamacionesUrl()));aceptaciones.save(a);}
 @Transactional public void aceptarPrueba(String tipo,Long orden,Long estudiante,String sub,AceptacionRequest r){var c=actual();if(r==null||!Boolean.TRUE.equals(r.acepta())||!Objects.equals(c.getVersion(),r.version()))throw new IllegalArgumentException("Acepta el aviso de prueba vigente antes de continuar.");if(aceptaciones.existsByTipoAndOrdenIdAndSujetoAndVersionComercial(tipo,orden,sub,c.getVersion()))return;var a=new AceptacionCompra();a.setTipo(tipo);a.setOrdenId(orden);a.setEstudianteId(estudiante);a.setSujeto(sub);a.setVersionComercial(c.getVersion());a.setFecha(Instant.now());a.setTextoAceptado("Modo de prueba: utiliza únicamente cuentas y tarjetas de prueba");aceptaciones.save(a);}
 private ConfiguracionComercial actual(){return repo.findById(1L).orElseThrow(()->new IllegalStateException("Configuración comercial no inicializada"));}
 private DatosComerciales datos(ConfiguracionComercial c){return new DatosComerciales(c.getVersion(),c.getRazonSocial(),c.getRuc(),c.getDireccion(),c.getEmailSoporte(),c.getTerminos(),c.getPrivacidad(),c.getReembolsos(),c.getReclamacionesUrl(),c.isPublicada());}
 public static boolean https(String s){try{var u=URI.create(s);return "https".equalsIgnoreCase(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&!Set.of("localhost","127.0.0.1","::1").contains(u.getHost());}catch(Exception e){return false;}}
 static List<String> pendientes(ConfiguracionComercial c){var p=new ArrayList<String>();if(c.getRazonSocial().isBlank())p.add("Nombre o razón social");if(!c.getRuc().matches("[0-9]{11}"))p.add("RUC de 11 dígitos");if(c.getDireccion().isBlank())p.add("Domicilio del vendedor");if(!c.getEmailSoporte().matches("[^@ ]+@[^@ ]+[.][^@ ]+"))p.add("Correo de atención");if(c.getTerminos().length()<80)p.add("Condiciones de compra");if(c.getPrivacidad().length()<80)p.add("Política de privacidad");if(c.getReembolsos().length()<80)p.add("Política de reembolsos");if(!https(c.getReclamacionesUrl()))p.add("URL HTTPS del Libro de Reclamaciones");if(!c.isPublicada())p.add("Publicar información comercial");return p;}
}
